// ============================================
// MOBILE TABLE SCROLL AFFORDANCE (UX)
// ============================================
document.addEventListener("DOMContentLoaded", function() {
  const wrappers = document.querySelectorAll(".table-wrapper");
  
  wrappers.forEach(wrapper => {
    // Check if the table overflows (scrollable)
    const checkScrollable = () => {
      if (wrapper.scrollWidth > wrapper.clientWidth) {
        wrapper.classList.add("is-scrollable");
      } else {
        wrapper.classList.remove("is-scrollable");
      }
    };
    
    // Check if scrolled to end
    const checkScrollEnd = () => {
      const isAtEnd = wrapper.scrollLeft + wrapper.clientWidth >= wrapper.scrollWidth - 5;
      if (isAtEnd) {
        wrapper.classList.add("is-scrolled-end");
      } else {
        wrapper.classList.remove("is-scrolled-end");
      }
    };
    
    // Run on load and resize
    checkScrollable();
    window.addEventListener("resize", checkScrollable);
    
    // Run on scroll
    wrapper.addEventListener("scroll", checkScrollEnd);
    wrapper.addEventListener("scroll", checkScrollable);
  });
});



