// ============================================
// PHASE 3: SKELETON LOADING & THEME TOGGLE
// ============================================
class SkeletonManager {
  constructor() {
    this.skeletons = document.querySelectorAll("[data-skeleton]");
  }
  show(sectionId) {
    const skeleton = document.querySelector([data-skeleton=""]);
    const content = document.querySelector([data-content=""]);
    if (skeleton) skeleton.style.display = 'block';
    if (content) content.style.display = 'none';
  }
  hide(sectionId) {
    const skeleton = document.querySelector([data-skeleton=""]);
    const content = document.querySelector([data-content=""]);
    if (skeleton) skeleton.style.display = 'none';
    if (content) content.style.display = 'block';
  }
  load(sectionId, delay = 800) {
    this.show(sectionId);
    return new Promise((resolve) => {
      setTimeout(() => {
        this.hide(sectionId);
        resolve();
      }, delay);
    });
  }
}

document.addEventListener('DOMContentLoaded', function() {
  // Skeleton Loading on Page Load
  const skeleton = new SkeletonManager();
  const sections = ['market-snapshot', 'daily-wraps', 'top-gainers'];
  sections.forEach(section => { skeleton.show(section); });
  setTimeout(() => {
    sections.forEach(section => { skeleton.hide(section); });
  }, 800);

  // Theme Toggle
  const toggle = document.getElementById('themeToggle');
  const html = document.documentElement;
  const savedTheme = localStorage.getItem('theme') || 'dark';
  html.setAttribute('data-theme', savedTheme);
  
  if (toggle) {
    toggle.addEventListener('click', function() {
      const currentTheme = html.getAttribute('data-theme');
      const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
      html.setAttribute('data-theme', newTheme);
      localStorage.setItem('theme', newTheme);
    });
  }
  
  if (!localStorage.getItem('theme')) {
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
    html.setAttribute('data-theme', prefersDark.matches ? 'dark' : 'light');
  }
});

